import React, { useState, useEffect } from 'react';
import './App.css';

function App() {
  // --- ESTADOS DE AUTENTICACIÓN ---
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');

  // --- ESTADOS DE PANTALLA ---
  const [pantalla, setPantalla] = useState('catalogo'); 
  const [productos, setProductos] = useState([]);

  // --- BÓVEDA DE IMÁGENES (Local Storage) ---
  const [storedImages, setStoredImages] = useState(() => {
    const saved = localStorage.getItem('catalog_images_paisita');
    return saved ? JSON.parse(saved) : {};
  });

  // --- CATALOGO MAESTRO (Persistencia) ---
  const [catalog, setCatalog] = useState(() => {
    const savedCatalog = localStorage.getItem('master_catalog_paisita');
    return savedCatalog ? JSON.parse(savedCatalog) : [];
  });

  const [ventasDelDia, setVentasDelDia] = useState(() => {
    const guardadas = localStorage.getItem('ventas_paisita');
    return guardadas ? JSON.parse(guardadas) : [];
  });

  const [fechaHoy] = useState(() => {
    return new Date().toLocaleDateString('es-CO', { 
      weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' 
    });
  });

  // --- Formulario ---
  const [nombre, setNombre] = useState('Empanada');
  const [categoria, setCategoria] = useState('Fritos');
  const [imagenUrl, setImagenUrl] = useState(''); 
  const [tempImage, setTempImage] = useState(null); // Para la carga de archivo local
  const [precioCosto, setPrecioCosto] = useState(1500);
  const [impuesto, setImpuesto] = useState('19'); 
  const [precioVenta, setPrecioVenta] = useState(2500);
  const [stock, setStock] = useState(20);

  // --- EFECTOS ---
  useEffect(() => {
    localStorage.setItem('ventas_paisita', JSON.stringify(ventasDelDia));
  }, [ventasDelDia]);

  useEffect(() => {
    localStorage.setItem('master_catalog_paisita', JSON.stringify(catalog));
  }, [catalog]);

  useEffect(() => {
    localStorage.setItem('catalog_images_paisita', JSON.stringify(storedImages));
  }, [storedImages]);

  useEffect(() => {
    if (isLoggedIn) {
      obtenerInventarioBackend();
    }
  }, [isLoggedIn]);

  const obtenerInventarioBackend = async () => {
    try {
      const respuesta = await fetch('http://localhost:8080/api/productos');
      if (respuesta.ok) {
        const datos = await respuesta.json();
        setProductos(datos);
      }
    } catch (error) {
      console.error("Error al sincronizar con Spring Boot:", error);
    }
  };

  // ELIMINAR TODO EL INVENTARIO DE LA BASE DE DATOS
  const handleBorrarTodo = async () => {
    if (window.confirm("🚨 ¿ATENCIÓN! ¿Estás seguro de que deseas ELIMINAR TODOS los productos de la base de datos? Esta acción no se puede deshacer.")) {
      try {
        const respuesta = await fetch('http://localhost:8080/api/productos/vaciar', {
          method: 'DELETE'
        });
        if (respuesta.ok) {
          alert("Base de datos vaciada con éxito. Inventario en cero.");
          setProductos([]);
          setVentasDelDia([]);
          setStoredImages({});
          localStorage.removeItem('ventas_paisita');
          localStorage.removeItem('catalog_images_paisita');
        } else {
          alert("El backend rechazó la solicitud de borrado.");
        }
      } catch (error) {
        alert("Error de conexión al intentar borrar los datos.");
      }
    }
  };

  // MODIFICAR STOCK DIRECTAMENTE DESDE EL CATÁLOGO
  const cambiarStockManual = async (producto) => {
    const nuevoStockString = prompt(`Modificar existencias de: ${producto.nombre}\nCantidad actual: ${producto.stock} uds.\n\nEscribe el nuevo stock total:`, producto.stock);

    if (nuevoStockString === null) return;

    const nuevoStockNum = parseInt(nuevoStockString, 10);
    if (isNaN(nuevoStockNum) || nuevoStockNum < 0) {
      alert("Por favor ingresa un número entero válido y mayor o igual a cero.");
      return;
    }

    const productoActualizado = {
      ...producto,
      stock: nuevoStockNum
    };

    try {
      const respuesta = await fetch('http://localhost:8080/api/productos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(productoActualizado)
      });

      if (respuesta.ok) {
        obtenerInventarioBackend();
      } else {
        alert("No se pudo actualizar el stock en el servidor.");
      }
    } catch (error) {
      alert("Error de red al actualizar stock.");
    }
  };

  // REGISTRAR PRODUCTO
  const handleGuardar = async (e) => {
    e.preventDefault();

    const productoExistente = productos.find(
      (p) => p.nombre.toLowerCase().trim() === nombre.toLowerCase().trim()
    );

    if (productoExistente) {
      alert(`El producto "${nombre}" ya existe en el catálogo. Usa el botón "Modificar Stock" en la tarjeta correspondiente para alterar sus unidades.`);
      setPantalla('catalogo');
      return;
    }

    if (tempImage) {
      setStoredImages(prev => ({ ...prev, [nombre.trim()]: tempImage }));
    }

    const urlFinal = 'https://images.unsplash.com/photo-1628102477218-097561f38e6f?q=80&w=300&auto=format&fit=crop';

    const yaExisteEnCatalog = catalog.find(p => p.nombre.toLowerCase().trim() === nombre.toLowerCase().trim());
    if (!yaExisteEnCatalog) {
      setCatalog([...catalog, { nombre: nombre.trim(), categoria, imagenUrl: urlFinal, precioCosto: parseFloat(precioCosto), precioVenta: parseFloat(precioVenta) }]);
    }

    const nuevoProducto = {
      nombre: nombre.trim(),
      categoria,
      imagenUrl: urlFinal,
      precioCosto: parseFloat(precioCosto),
      impuesto: parseFloat(impuesto),
      precioVenta: parseFloat(precioVenta),
      stock: parseInt(stock)
    };

    try {
      const respuesta = await fetch('http://localhost:8080/api/productos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(nuevoProducto)
      });

      if (respuesta.ok) {
        alert("¡Producto inyectado correctamente!");
        setNombre(''); setCategoria(''); setTempImage(null); setPrecioCosto(''); setPrecioVenta(''); setStock('');
        obtenerInventarioBackend();
        setPantalla('catalogo');
      }
    } catch (error) {
      alert("Error de conexión con el backend.");
    }
  };

  const registrarVenta = (producto) => {
    if (producto.stock <= 0) {
      alert(`¡Alerta! Sin existencias de ${producto.nombre}.`);
      return;
    }

    const inventarioActualizado = productos.map((p) => {
      if (p.id === producto.id) return { ...p, stock: p.stock - 1 };
      return p;
    });
    setProductos(inventarioActualizado);

    // CORRECCIÓN: Nos aseguramos de tratar los datos como números obligatoriamente
    const pCosto = Number(producto.precioCosto || 0);
    const pImpuesto = Number(producto.impuesto || 0);
    const pVenta = Number(producto.precioVenta || 0);

    const costoRealConIva = pCosto * (1 + pImpuesto / 100);
    const gananciaNetaGenerada = pVenta - costoRealConIva;

    const nuevaVenta = {
      id: Date.now(),
      nombre: producto.nombre,
      precioVenta: pVenta,
      costoConIva: costoRealConIva,
      gananciaNeta: gananciaNetaGenerada,
      hora: new Date().toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit' })
    };

    setVentasDelDia([...ventasDelDia, nuevaVenta]);
  };

  const limpiarCierreCaja = () => {
    if (window.confirm("¿Seguro que deseas cerrar la jornada actual? Esto limpiará el reporte de hoy.")) {
      setVentasDelDia([]);
      localStorage.removeItem('ventas_paisita');
    }
  };

  const formatearMoneda = (v) => new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', minimumFractionDigits: 0 }).format(v);

  // CORRECCIÓN: Reducción segura para evitar NaN
  const ingresosTotales = ventasDelDia.reduce((sum, v) => sum + (Number(v.precioVenta) || 0), 0);
  const gananciasTotalesNetas = ventasDelDia.reduce((sum, v) => sum + (Number(v.gananciaNeta) || 0), 0);

  if (!isLoggedIn) {
    return (
      <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh', backgroundColor: '#f4f4f9' }}>
        <div style={{ background: 'white', padding: '2rem', borderRadius: '10px', boxShadow: '0 4px 6px rgba(0,0,0,0.1)', textAlign: 'center', width: '300px' }}>
          <h2>Iniciar Sesión</h2>
          <input type="text" placeholder="Usuario" value={username} onChange={(e) => setUsername(e.target.value)} style={{ width: '100%', padding: '10px', marginBottom: '10px' }} />
          <input type="password" placeholder="Contraseña" value={password} onChange={(e) => setPassword(e.target.value)} style={{ width: '100%', padding: '10px', marginBottom: '20px' }} />
          <button onClick={() => { if(username === 'admin' && password === '12345') setIsLoggedIn(true); else alert('Credenciales incorrectas'); }} style={{ width: '100%', padding: '10px', backgroundColor: '#333', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer' }}>Ingresar</button>
        </div>
      </div>
    );
  }

  return (
    <div className="app-layout">
      <header className="app-header">
        <div className="header-brand">
          <h1>El Paisita UP</h1>
          <p className="fecha-badge">📅 {fechaHoy}</p>
        </div>
        <nav className="header-nav">
          <button className={`nav-link ${pantalla === 'catalogo' ? 'active' : ''}`} onClick={() => setPantalla('catalogo')}>📦 Catálogo</button>
          <button className={`nav-link ${pantalla === 'formulario' ? 'active' : ''}`} onClick={() => setPantalla('formulario')}>➕ Ingresar Mercancía</button>
          <button className={`nav-link-alert ${pantalla === 'reporte' ? 'active' : ''}`} onClick={() => setPantalla('reporte')}>📊 Cierre de Caja ({ventasDelDia.length})</button>
          <button className="btn-nav-clear-database" onClick={handleBorrarTodo}>🔥 Reiniciar Todo</button>
        </nav>
      </header>

      <main className="app-content">
        {pantalla === 'catalogo' && (
          <div className="catalogo-view">
            <div className="seccion-titulo">
              <h2>Inventario Disponible</h2>
              <p>Módulo de facturación directa y alteración física de stock por ítem</p>
            </div>

            {productos.length === 0 ? (
              <div className="empty-state">No hay mercancía en el catálogo. Registra un ítem o limpia la caché de red.</div>
            ) : (
              <div className="grid-catalogo">
                {productos.map((prod) => (
                  <div key={prod.id} className="card-producto">
                    <div className="card-image-wrapper">
                      <img 
                        src={storedImages[prod.nombre] || prod.imagenUrl} 
                        alt={prod.nombre} 
                        style={{ width: '100%', height: '200px', objectFit: 'cover' }} 
                      />
                      <span className="categoria-tag">{prod.categoria}</span>
                    </div>
                    <div className="card-info">
                      <h3>{prod.nombre}</h3>
                      <div className="card-precios">
                        <div>
                          <span className="label-precio">P. Venta</span>
                          <span className="valor-venta">{formatearMoneda(Number(prod.precioVenta) || 0)}</span>
                        </div>
                        <div className="text-right">
                          <span className="label-precio">Costo base</span>
                          <span className="valor-costo">{formatearMoneda(Number(prod.precioCosto) || 0)}</span>
                        </div>
                      </div>

                      <div className="stock-status-bar">
                        <span className="stock-count">Existencia: <strong>{prod.stock} uds</strong></span>
                        <div className="progreso-stock" style={{width: `${Math.min((prod.stock/50)*100, 100)}%`, backgroundColor: prod.stock < 5 ? '#E8C5C8' : '#C1D7C3'}}></div>
                      </div>

                      <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '8px' }}>
                        <button className="btn-vender-card" onClick={() => registrarVenta(prod)} disabled={prod.stock <= 0}>
                          {prod.stock <= 0 ? '🚫 Agotado' : '🛒 Vender'}
                        </button>
                        <button className="btn-modificar-stock" onClick={() => cambiarStockManual(prod)} title="Ajustar inventario físico">
                          ✏️ Stock
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {pantalla === 'formulario' && (
          <div className="form-container-centered">
            <div className="form-card">
              <h2 className="form-title">Registro Único de Producto <span>Nombres repetidos serán rebotados para evitar redundancia</span></h2>
              <form onSubmit={handleGuardar}>
                <div className="form-group">
                  <label className="form-label">Nombre del Producto</label>
                  <input type="text" value={nombre} onChange={(e) => setNombre(e.target.value)} className="form-input" required />
                </div>
                <div className="grid-2-col">
                  <div className="form-group">
                    <label className="form-label">Categoría</label>
                    <input type="text" value={categoria} onChange={(e) => setCategoria(e.target.value)} className="form-input" required />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Imagen (Del dispositivo)</label>
                    <input 
                      type="file" 
                      accept="image/*" 
                      onChange={(e) => {
                        const file = e.target.files[0];
                        if (file) {
                          const reader = new FileReader();
                          reader.onloadend = () => {
                            setTempImage(reader.result);
                          };
                          reader.readAsDataURL(file);
                        }
                      }} 
                      className="form-input" 
                    />
                  </div>
                </div>
                <div className="grid-2-col">
                  <div className="form-group">
                    <label className="form-label">Precio Costo</label>
                    <input type="number" value={precioCosto} onChange={(e) => setPrecioCosto(Number(e.target.value))} className="form-input" required />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Impuesto</label>
                    <select value={impuesto} onChange={(e) => setImpuesto(e.target.value)} className="form-input">
                      <option value="19">IVA 19%</option>
                      <option value="8">INC 8%</option>
                      <option value="0">Exento</option>
                    </select>
                  </div>
                </div>
                <div className="suggested-box">
                  <p className="suggested-title">Margen de Rentabilidad Sugerido (30%)</p>
                  <div className="suggested-price">{formatearMoneda(Number(precioCosto) * (1 + parseFloat(impuesto)/100) * 1.3)}</div>
                </div>
                <div className="grid-2-col">
                  <div className="form-group">
                    <label className="form-label">Precio Final Venta</label>
                    <input type="number" value={precioVenta} onChange={(e) => setPrecioVenta(Number(e.target.value))} className="form-input" required />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Cantidad Inicial</label>
                    <input type="number" value={stock} onChange={(e) => setStock(Number(e.target.value))} className="form-input" required />
                  </div>
                </div>
                <button type="submit" className="btn-submit">Inyectar Nuevo Producto</button>
              </form>
            </div>
          </div>
        )}

        {pantalla === 'reporte' && (
          <div className="reporte-view">
            <div className="kpi-dashboard">
              <div className="kpi-card text-pastel-pink">
                <h3>Volumen de Ventas</h3>
                <p className="kpi-valor">{ventasDelDia.length} uds</p>
              </div>
              <div className="kpi-card text-pastel-blue">
                <h3>Recaudo de Caja</h3>
                <p className="kpi-valor">{formatearMoneda(ingresosTotales)}</p>
              </div>
              <div className="kpi-card text-pastel-green">
                <h3>Utilidad Neta</h3>
                <p className="kpi-valor">{formatearMoneda(gananciasTotalesNetas)}</p>
                <span className="kpi-subtext">Margen limpio deducidos costos y tasas impositivas</span>
              </div>
            </div>
            <div className="form-card full-width-card">
              <div className="reporte-header">
                <h2>Cierre Diario de Operaciones</h2>
                <button className="btn-clean-caja" onClick={limpiarCierreCaja}>🔒 Cerrar Caja</button>
              </div>
              {ventasDelDia.length === 0 ? (
                <p className="empty-state">No hay registros de transacciones para la fecha.</p>
              ) : (
                <table className="tabla-reporte">
                  <thead>
                    <tr>
                      <th>Timestamp</th>
                      <th>Ítem</th>
                      <th>Ingreso Bruto</th>
                      <th>Costo Real</th>
                      <th>Margen de Ganancia</th>
                    </tr>
                  </thead>
                  <tbody>
                    {ventasDelDia.map((v) => (
                      <tr key={v.id}>
                        <td>{v.hora}</td>
                        <td style={{ color: '#E3CBB3', fontWeight: '500' }}>{v.nombre}</td>
                        <td>{formatearMoneda(Number(v.precioVenta) || 0)}</td>
                        <td>{formatearMoneda(Number(v.costoConIva) || 0)}</td>
                        <td style={{ color: '#C1D7C3', fontWeight: '600' }}>+{formatearMoneda(Number(v.gananciaNeta) || 0)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
